# ([] = tanpa jamak) · MEAN: arti (ditambahkan ke MEAN_FIX).
AR = {}
JENIS = {}
MUDHARI = {}
JAMAK = {}
MEAN = {}


def add(ar=None, jenis=None, mudhari=None, jamak=None, mean=None):
    for d, src in ((AR, ar), (JENIS, jenis), (MUDHARI, mudhari), (JAMAK, jamak), (MEAN, mean)):
        if src:
            d.update(src)


